#include "Prescription.h"
#include "Utils.h"
Prescription::Prescription(){prescriptionID=appointmentID=patientID=doctorID=0; date[0]=medicines[0]=notes[0]='\0';}
Prescription::Prescription(int x,int a,int p,int d,const char* dt,const char* m,const char* n){prescriptionID=x; appointmentID=a; patientID=p; doctorID=d; Utils::copyArr(date,dt,11); Utils::copyArr(medicines,m,500); Utils::copyArr(notes,n,300);} 
int Prescription::getPrescriptionID() const{return prescriptionID;} int Prescription::getAppointmentID() const{return appointmentID;} int Prescription::getPatientID() const{return patientID;} int Prescription::getDoctorID() const{return doctorID;} const char* Prescription::getDate() const{return date;} const char* Prescription::getMedicines() const{return medicines;} const char* Prescription::getNotes() const{return notes;} void Prescription::setPrescriptionID(int v){prescriptionID=v;} void Prescription::setAppointmentID(int v){appointmentID=v;} void Prescription::setPatientID(int v){patientID=v;} void Prescription::setDoctorID(int v){doctorID=v;} void Prescription::setDate(const char* v){Utils::copyArr(date,v,11);} void Prescription::setMedicines(const char* v){Utils::copyArr(medicines,v,500);} void Prescription::setNotes(const char* v){Utils::copyArr(notes,v,300);} 
